/**
 * =========================================================================
 * ⚙️ STEP 1: CONFIGURE REPO, TOKEN & EMAIL HERE
 * =========================================================================
 * When testing another repository, ONLY CHANGE REPO_OWNER / REPO_NAME below!
 * The entire pipeline will automatically execute against that repo.
 */

// 1. Target GitHub Repository (Change this when testing another repo!)
const REPO_OWNER = 'kunalpawar9403'; // GitHub user or organization
const REPO_NAME = 'life-harmony';    // Repository name to test
const DEFAULT_REF = 'main';          // Branch to checkout and test
const ENVIRONMENT = 'staging';       // Target environment tag

// 2. Your GitHub Personal Access Token (Paste in n8n Cloud directly)
const GITHUB_TOKEN = $env.GITHUB_TOKEN || 'REPLACE_WITH_YOUR_GITHUB_PAT';

// 3. Final Report Notification Email
const RECIPIENT_EMAIL = 'kunalpawar0309@gmail.com';

// 4. Optional Webhook (Slack, Discord, Teams)
const NOTIFICATION_WEBHOOK = '';

// =========================================================================
// Dynamic Context Normalization & Correlation ID Generation
// =========================================================================
const incoming = $input.first()?.json || {};
const body = incoming.body || incoming;

const timestamp = Date.now();
const randomStr = Math.random().toString(36).substring(2, 9);
const correlationId = body.correlation_id || `qa_corr_${timestamp}_${randomStr}`;

const finalOwner = (body.repo_owner || REPO_OWNER).trim();
const finalRepo = (body.repo_name || REPO_NAME).trim();
const finalRef = (body.ref || DEFAULT_REF).trim();
const finalCommitSha = (body.commit_sha || '').trim();
const finalToken = (body.github_token || GITHUB_TOKEN).trim();
const finalEmail = (body.recipient_email || RECIPIENT_EMAIL).trim();
const finalWebhook = (body.notification_webhook || NOTIFICATION_WEBHOOK).trim();

return [{
  json: {
    github_token: finalToken,
    repo_owner: finalOwner,
    repo_name: finalRepo,
    ref: finalRef,
    commit_sha: finalCommitSha,
    environment: ENVIRONMENT,
    recipient_email: finalEmail,
    notification_webhook: finalWebhook,
    correlation_id: correlationId,
    triggered_at: new Date().toISOString(),
    poll_count: 0,
    max_polls: 30,
    poll_interval_seconds: 15,
    is_completed: false,
    is_timed_out: false
  }
}];

