// Match active run & increment bounded retry counter
const config = $('⚙️ Set Your GitHub Config & Token').first().json;
const currentPollCount = (config.poll_count || 0) + 1;
config.poll_count = currentPollCount;

const runsPayload = $input.first().json || {};
const runs = runsPayload.workflow_runs || [];

const triggerTimestamp = new Date(config.triggered_at).getTime() - 60000;
let matchedRun = null;

for (const r of runs) {
  const runCreatedAt = new Date(r.created_at).getTime();
  const branchMatch = r.head_branch === config.ref;
  const shaMatch = config.commit_sha ? r.head_sha.startsWith(config.commit_sha) : true;

  if (runCreatedAt >= triggerTimestamp && (branchMatch || shaMatch)) {
    matchedRun = r;
    break;
  }
}

if (!matchedRun && runs.length > 0) {
  matchedRun = runs[0];
}

const isCompleted = matchedRun ? matchedRun.status === 'completed' : false;
const isTimedOut = currentPollCount >= config.max_polls;

return [{
  json: {
    ...config,
    poll_count: currentPollCount,
    is_completed: isCompleted,
    is_timed_out: isTimedOut,
    run_id: matchedRun ? matchedRun.id : null,
    run_number: matchedRun ? matchedRun.run_number : null,
    head_sha: matchedRun ? matchedRun.head_sha : config.commit_sha,
    status: matchedRun ? matchedRun.status : 'not_found',
    conclusion: matchedRun ? matchedRun.conclusion : null,
    html_url: matchedRun ? matchedRun.html_url : null,
    updated_at: matchedRun ? matchedRun.updated_at : null
  }
}];

