// Strict Conclusion Verification
const data = $input.first().json;

const hasRunId = Boolean(data.run_id);
const isSuccessConclusion = data.conclusion === 'success';
const shaMatches = data.commit_sha ? data.head_sha.startsWith(data.commit_sha) : true;

const strictlyVerified = hasRunId && isSuccessConclusion && shaMatches;

return [{
  json: {
    ...data,
    verified_success: strictlyVerified,
    sha_verified: shaMatches,
    failure_reason: strictlyVerified ? null : (!shaMatches ? 'Commit SHA mismatch' : `Run concluded with: ${data.conclusion}`)
  }
}];

// Prepare Rich HTML QA Report for Email
const verifiedData = $('Verify Conclusion & SHA').first()?.json || {};
const isPass = verifiedData.verified_success === true;
const statusColor = isPass ? '#10B981' : '#EF4444';
const statusBadge = isPass ? '🟢 ALL TESTS PASSED' : '🔴 TESTS FAILED - TRIAGE OPENED';

const recipientEmail = verifiedData.recipient_email || 'kunalpawar0309@gmail.com';
const repo = `${verifiedData.repo_owner}/${verifiedData.repo_name}`;
const runUrl = verifiedData.html_url || `https://github.com/${repo}/actions`;
const runNumber = verifiedData.run_number || '1';
const sha = verifiedData.head_sha || 'latest';

const subject = `[Playwright QA Report] ${isPass ? 'PASSED' : 'ACTION REQUIRED'}: ${repo} (Run #${runNumber})`;

const html = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; background-color: #0F172A; color: #F8FAFC; margin: 0; padding: 24px; }
    .container { max-width: 600px; margin: 0 auto; background-color: #1E293B; border-radius: 12px; border: 1px solid #334155; overflow: hidden; }
    .header { background: linear-gradient(135deg, #1E1B4B 0%, #311042 100%); padding: 28px 24px; border-bottom: 1px solid #334155; text-align: center; }
    .badge { display: inline-block; padding: 6px 14px; border-radius: 9999px; font-weight: bold; font-size: 13px; letter-spacing: 0.5px; background-color: ${statusColor}22; color: ${statusColor}; border: 1px solid ${statusColor}; margin-bottom: 12px; }
    .content { padding: 24px; }
    .grid { margin: 18px 0; border: 1px solid #334155; border-radius: 8px; overflow: hidden; }
    .row { display: flex; padding: 10px 14px; border-bottom: 1px solid #334155; background: #0F172A55; }
    .row:last-child { border-bottom: none; }
    .col-label { width: 140px; font-weight: 600; color: #94A3B8; font-size: 13px; }
    .col-value { flex: 1; color: #F1F5F9; font-size: 13px; word-break: break-all; }
    .summary-box { background: #0F172A; border-left: 4px solid ${statusColor}; padding: 14px; border-radius: 4px; margin: 20px 0; }
    .btn { display: inline-block; background-color: #6366F1; color: #ffffff !important; padding: 12px 24px; border-radius: 8px; text-decoration: none; font-weight: 600; font-size: 14px; margin-top: 10px; }
    .footer { padding: 18px 24px; background: #0F172A; text-align: center; font-size: 11px; color: #64748B; border-top: 1px solid #334155; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <div class="badge">${statusBadge}</div>
      <h2 style="margin: 0; color: #FFFFFF;">Automated Playwright QA Report</h2>
      <p style="margin: 6px 0 0; color: #94A3B8; font-size: 14px;">${repo}</p>
    </div>
    <div class="content">
      <div class="summary-box">
        <strong style="color: ${statusColor};">Status Overview:</strong>
        <p style="margin: 6px 0 0; color: #CBD5E1; font-size: 13px;">
          ${isPass 
            ? 'All Playwright end-to-end tests completed with 100% success on GitHub Actions. No regressions detected.' 
            : 'Automated test suite detected failures. An automated Antigravity triage ticket was opened on GitHub.'}
        </p>
      </div>

      <div class="grid">
        <div class="row"><div class="col-label">Repository:</div><div class="col-value">${repo}</div></div>
        <div class="row"><div class="col-label">Commit SHA:</div><div class="col-value"><code>${sha.substring(0, 7)} (${sha})</code></div></div>
        <div class="row"><div class="col-label">Branch / Ref:</div><div class="col-value">${verifiedData.ref}</div></div>
        <div class="row"><div class="col-label">GitHub Run:</div><div class="col-value">Run #${runNumber}</div></div>
        <div class="row"><div class="col-label">Correlation ID:</div><div class="col-value"><code>${verifiedData.correlation_id}</code></div></div>
        <div class="row"><div class="col-label">Execution Time:</div><div class="col-value">${new Date().toUTCString()}</div></div>
      </div>

      <div style="text-align: center; margin: 24px 0;">
        <a href="${runUrl}" class="btn" target="_blank">View Playwright Report & Artifacts &rarr;</a>
      </div>
    </div>
    <div class="footer">
      Automated by n8n Cloud &bull; GitHub Actions &bull; Antigravity Desktop QA Orchestrator
    </div>
  </div>
</body>
</html>
`;

return [{
  json: {
    ...verifiedData,
    email_recipient: recipientEmail,
    email_subject: subject,
    email_html: html
  }
}];

const errData = $input.first().json || {};
const exec = errData.execution || {};

return [{
  json: {
    alert: 'WORKFLOW_FATAL_ERROR',
    workflow: exec.workflowName || 'Playwright QA Orchestrator',
    execution_id: exec.id || 'unknown',
    error: errData.error?.message || 'Uncaught error in workflow',
    node: errData.error?.node?.name || 'unknown',
    timestamp: new Date().toISOString()
  }
}];
